import threading

class Queue:
    def __init__(self):
        # ordered storage of jobs to preserve insertion order
        self._jobs = {}
        self._order = []  # list of job_id in insertion order
        self._lock = threading.Lock()

    def add(self, job_id):
        with self._lock:
            if job_id not in self._jobs:
                self._jobs[job_id] = {
                    'state': 'queued',
                    'worker': None,
                    'token': None,
                    'expires': None,
                }
                self._order.append(job_id)

    def claim(self, worker, now, ttl):
        if ttl <= 0:
            return None
        with self._lock:
            for jid in self._order:
                job = self._jobs.get(jid)
                if not job:
                    continue
                if job['state'] == 'queued' or (
                    job['state'] == 'running' and job['expires'] <= now
                ):
                    token = uuid.uuid4().hex
                    job['state'] = 'running'
                    job['worker'] = worker
                    job['token'] = token
                    job['expires'] = now + ttl
                    return {
                        'job_id': jid,
                        'worker': worker,
                        'token': token,
                    }
        return None

    def renew(self, lease, now, ttl):
        if ttl <= 0:
            return False
        with self._lock:
            jid = lease.get('job_id')
            job = self._jobs.get(jid)
            if not job:
                return False
            if (
                job['state'] == 'running'
                and job['worker'] == lease.get('worker')
                and job['token'] == lease.get('token')
                and job['expires'] > now
            ):
                job['expires'] = now + ttl
                return True
        return False

    def complete(self, lease, now):
        with self._lock:
            jid = lease.get('job_id')
            job = self._jobs.get(jid)
            if not job:
                return False
            if (
                job['state'] == 'running'
                and job['worker'] == lease.get('worker')
                and job['token'] == lease.get('token')
                and job['expires'] > now
            ):
                # remove job
                del self._jobs[jid]
                self._order.remove(jid)
                return True
        return False
